# We'll match by title and artist name
archive_song_ids = []
for song in archive_songs:
    results = apis.spotify.search_songs(query=song["title"], access_token=spotify_token, page_limit=20)
    # Find exact match by title and artist
    found = None
    for r in results:
        if r["title"].lower() == song["title"].lower():
            # Check if any artist matches
            for artist in r["artists"]:
                if artist["name"].lower() == song["artist"].lower():
                    found = r["song_id"]
                    break
            if found:
                break
    if found:
        archive_song_ids.append(found)
        print(f"Found: {song['title']} by {song['artist']} -> song_id {found}")
    else:
        print(f"NOT FOUND: {song['title']} by {song['artist']}")

print(f"\nTotal found: {len(archive_song_ids)}")

